def transform(grid):
    h, w = len(grid), len(grid[0])

    # The template is the least frequent nonzero color.
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    template_color = min(counts, key=counts.get)

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == template_color]
    min_r = min(r for r, c in points)
    max_r = max(r for r, c in points)
    min_c = min(c for r, c in points)
    max_c = max(c for r, c in points)
    offsets = [(r - min_r, c - min_c) for r, c in points]

    out = [row[:] for row in grid]
    th, tw = max_r - min_r + 1, max_c - min_c + 1

    # Find places where every template cell lies over a zero, then color them.
    matches = []
    for top in range(h - th + 1):
        for left in range(w - tw + 1):
            if all(grid[top + dr][left + dc] == 0 for dr, dc in offsets):
                matches.append((top, left))

    for top, left in matches:
        for dr, dc in offsets:
            out[top + dr][left + dc] = template_color

    return out
